/**
 * @method
 * @name backpack#fetchMyTrades
 * @description fetch all trades made by the user
 * @see https://docs.backpack.exchange/#tag/History/operation/get_fills
 * @param {string} symbol unified market symbol
 * @param {int} [since] the earliest time in ms to fetch trades for
 * @param {int} [limit] the maximum number of trades structures to retrieve (default 100, max 1000)
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {int} [params.until] the latest time in ms to fetch trades for
 * @param {string} [params.fillType] 'User' (default) 'BookLiquidation' or 'Adl' or 'Backstop' or 'Liquidation' or 'AllLiquidation' or 'CollateralConversion' or 'CollateralConversionAndSpotLiquidation'
 * @returns {Trade[]} a list of [trade structures]{@link https://docs.ccxt.com/?id=trade-structure}
 */
func (this *Backpack) FetchMyTradesAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchMyTradesBody(ch, optionalArgs...)
	return ch
}
func (this *Backpack) fetchMyTradesBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var symbol *string = GetArgStringPtr(optionalArgs, 0, nil)
	_ = symbol
	var since *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	var request map[string]any = map[string]any{}
	var market map[string]any = nil
	if symbol != nil {
		market = this.Market(symbol)
		request["symbol"] = market["id"]
	}
	if since != nil {
		request["from"] = since
	}
	if limit != nil {
		request["limit"] = limit
	}
	var until *int64 = this.SafeInteger(params, "until")
	var paramsOmitted map[string]any = func() map[string]any {
		if until != nil {
			return MapTyped(this.Omit(params, []any{"until"}))
		}
		return params
	}()
	if until != nil {
		request["to"] = until
	}
	var fillType *string = this.SafeString(paramsOmitted, "fillType")
	if fillType == nil {
		request["fillType"] = "User" // default
	}

	var response []any = ListTyped(PanicOnError((<-this.PrivateGetWapiV1HistoryFills(this.Extend(request, paramsOmitted))).Raw))
	var responseList []any = this.ToArray(response)

	ch <- this.ParseTrades(responseList, market, since, limit)
	return nil
}
func (this *Backpack) ParseTrade(trade any, optionalArgs ...any) any {
	//
	// fetchTrades
	//     {
	//         "id": 8721563,
	//         "isBuyerMaker": false,
	//         "price": "117427.6",
	//         "quantity": "0.00016",
	//         "quoteQuantity": "18.788416",
	//         "timestamp": 1753123916819
	//     }
	//
	// fetchMyTrades
	//     {
	//         "clientId": null,
	//         "fee": "0.004974",
	//         "feeSymbol": "USDC",
	//         "isMaker": false,
	//         "orderId": "4238907375",
	//         "price": "3826.15",
	//         "quantity": "0.0026",
	//         "side": "Bid",
	//         "symbol": "ETH_USDC_PERP",
	//         "systemOrderType": null,
	//         "timestamp": "2025-07-27T17:39:00.092",
	//         "tradeId": 9748827
	//     }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var id *string = this.SafeString2(trade, "id", "tradeId")
	var marketId *string = this.SafeString(trade, "symbol")
	var marketResolved map[string]any = this.SafeMarket(marketId, market)
	var price *string = this.SafeString(trade, "price")
	var amount *string = this.SafeString(trade, "quantity")
	var isBuyerMaker *bool = this.SafeBool(trade, "isBuyerMaker")
	var side *string = this.ParseOrderSide(this.SafeString(trade, "side"))
	var isMaker *bool = this.SafeBool(trade, "isMaker")
	var takerOrMaker *string = nil
	if isMaker != nil {
		takerOrMaker = SafeStringPtr(func() string {
			if isMaker != nil && *isMaker {
				return "maker"
			}
			return "taker"
		}())
	} else if isBuyerMaker != nil {
		takerOrMaker = SafeStringPtr("taker")
		side = SafeStringPtr(func() string {
			if isBuyerMaker != nil && *isBuyerMaker {
				return "sell"
			}
			return "buy"
		}())
	}
	var orderId *string = this.SafeString(trade, "orderId")
	var fee map[string]any = nil
	var feeAmount *string = this.SafeString(trade, "fee")
	var timestamp *int64 = this.SafeInteger(trade, "timestamp")
	if feeAmount != nil {
		// if fetchMyTrades
		var datetime *string = this.SafeString(trade, "timestamp")
		timestamp = this.Parse8601(datetime)
	}
	var feeSymbol *string = this.SafeCurrencyCode(this.SafeString(trade, "feeSymbol"))
	if feeAmount != nil {
		fee = map[string]any{
			"cost":     feeAmount,
			"currency": feeSymbol,
			"rate":     nil,
		}
	}
	return this.SafeTrade(map[string]any{
		"info":         trade,
		"timestamp":    timestamp,
		"datetime":     this.Iso8601(timestamp),
		"symbol":       marketResolved["symbol"],
		"id":           id,
		"order":        orderId,
		"type":         nil,
		"side":         side,
		"takerOrMaker": takerOrMaker,
		"price":        price,
		"amount":       amount,
		"cost":         nil,
		"fee":          fee,
	}, marketResolved)
}

