func (this *Backpack) withdrawBody(ch chan any, code string, amount any, address any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var tag *string = GetArgStringPtr(optionalArgs, 0, nil)
	_ = tag
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	var currency map[string]any = this.Currency(code)
	var request map[string]any = map[string]any{
		"symbol":   currency["id"],
		"quantity": this.NumberToString(amount),
		"address":  address,
	}
	if tag != nil {
		request["clientId"] = tag // memo or tag
	}
	var networkCodequeryVariable []any = this.HandleNetworkCodeAndParams(params)
	var networkCode *string = SafeStringPtr(GetValue(networkCodequeryVariable, 0))
	var query map[string]any = MapTyped(GetValue(networkCodequeryVariable, 1))
	var networkId any = this.NetworkCodeToId(networkCode, this.SafeString(currency, "code"))
	if networkId == nil {
		panic(BadRequest(this.Id + " withdraw() requires a network parameter"))
	}
	request["blockchain"] = networkId

	var response map[string]any = MapTyped(PanicOnError((<-this.PrivatePostWapiV1CapitalWithdrawals(this.Extend(request, query))).Raw))

	ch <- this.ParseTransaction(response, currency)
	return nil
}
func (this *Backpack) ParseTransaction(transaction any, optionalArgs ...any) any {
	//
	// fetchDeposits
	//     [
	//         {
	//             "createdAt": "2025-07-23T13:55:54.267",
	//             "fiatAmount": null,
	//             "fiatCurrency": null,
	//             "fromAddress": "0x2e3ab3e88a7dbdc763aadf5b28c18fb085af420a",
	//             "id": 6695353,
	//             "institutionBic": null,
	//             "platformMemo": null,
	//             "quantity": "120",
	//             "source": "ethereum",
	//             "status": "confirmed",
	//             "symbol": "USDC",
	//             "toAddress": "0xfBe7CbfCde93c8a4204a4be6B56732Eb32690170",
	//             "transactionHash": "0x58edaac415398d617b34c6673fffcaf0024990d5700565030119db5cbf3765d1"
	//         }
	//     ]
	//
	// withdraw
	//     {
	//         "accountIdentifier": null,
	//         "bankIdentifier": null,
	//         "bankName": null,
	//         "blockchain": "Ethereum",
	//         "clientId": null,
	//         "createdAt": "2025-08-13T19:27:13.817",
	//         "fee": "3",
	//         "fiatFee": null,
	//         "fiatState": null,
	//         "fiatSymbol": null,
	//         "id": 5479929,
	//         "identifier": null,
	//         "isInternal": false,
	//         "providerId": null,
	//         "quantity": "10",
	//         "status": "pending",
	//         "subaccountId": null,
	//         "symbol": "USDC",
	//         "toAddress": "0x0ad42b8e602c2d3d475ae52d678cf63d84ab2749",
	//         "transactionHash": null,
	//         "triggerAt": null
	//     }
	//
	// fetchWithdrawals
	//     [
	//         {
	//             "accountIdentifier": null,
	//             "bankIdentifier": null,
	//             "bankName": null,
	//             "blockchain": "Ethereum",
	//             "clientId": null,
	//             "createdAt": "2025-08-13T19:27:13.817",
	//             "fee": "3",
	//             "fiatFee": null,
	//             "fiatState": null,
	//             "fiatSymbol": null,
	//             "id": 5479929,
	//             "identifier": null,
	//             "isInternal": false,
	//             "providerId": null,
	//             "quantity": "10",
	//             "status": "confirmed",
	//             "subaccountId": null,
	//             "symbol": "USDC",
	//             "toAddress": "0x0ad42b8e602c2d3d475ae52d678cf63d84ab2749",
	//             "transactionHash": "0x658b6d082af4afa0d3cf85caf344ff7c19d980117726bf193b00d8850f8746a1",
	//             "triggerAt": null
	//         }
	//     ]
	//
	var currency map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = currency
	var status *string = this.ParseTransactionStatus(this.SafeString(transaction, "status"))
	var id *string = this.SafeString(transaction, "id")
	var txid *string = this.SafeString(transaction, "transactionHash")
	var coin *string = this.SafeString(transaction, "symbol")
	var code *string = this.SafeCurrencyCode(coin, currency)
	var timestamp *int64 = this.Parse8601(this.SafeString(transaction, "createdAt"))
	var amount *float64 = this.SafeNumber(transaction, "quantity")
	var networkId *string = this.SafeStringLower2(transaction, "source", "blockchain")
	var network *string = this.NetworkIdToCode(networkId, code)
	var addressTo *string = this.SafeString(transaction, "toAddress")
	var addressFrom *string = this.SafeString(transaction, "fromAddress")
	var tag *string = this.SafeString(transaction, "platformMemo")
	var feeCost *float64 = this.SafeNumber(transaction, "fee")
	var internal *bool = this.SafeBool(transaction, "isInternal", false)
	var fee map[string]any = nil
	if feeCost != nil {
		fee = map[string]any{
			"cost":     feeCost,
			"currency": code,
		}
	}
	return map[string]any{
		"info":        transaction,
		"id":          id,
		"txid":        txid,
		"timestamp":   timestamp,
		"datetime":    this.Iso8601(timestamp),
		"network":     network,
		"address":     nil,
		"addressTo":   addressTo,
		"addressFrom": addressFrom,
		"tag":         tag,
		"tagTo":       nil,
		"tagFrom":     nil,
		"type":        nil,
		"amount":      amount,
		"currency":    code,
		"status":      status,
		"updated":     nil,
		"internal":    internal,
		"comment":     nil,
		"fee":         fee,
	}
}
func (this *Backpack) ParseTransactionStatus(status *string) *string {
	var statuses map[string]any = map[string]any{
		"cancelled":            "cancelled",
		"confirmed":            "ok",
		"declined":             "declined",
		"expired":              "expired",
		"initiated":            "initiated",
		"pending":              "pending",
		"refunded":             "refunded",
		"information required": "pending",
	}
	return this.SafeString(statuses, status, status)
}

