func (this *Backpack) ParseOrder(order any, optionalArgs ...any) any {
	//
	//     {
	//         "clientId": null,
	//         "createdAt": 1753624283415,
	//         "executedQuantity": "0.001",
	//         "executedQuoteQuantity": "3.81428",
	//         "id": "4227701917",
	//         "orderType": "Market",
	//         "quantity": "0.001",
	//         "quoteQuantity": "3.82",
	//         "reduceOnly": null,
	//         "relatedOrderId": null,
	//         "selfTradePrevention": "RejectTaker",
	//         "side": "Bid",
	//         "status": "Filled",
	//         "stopLossLimitPrice": null,
	//         "stopLossTriggerBy": null,
	//         "stopLossTriggerPrice": null,
	//         "strategyId": null,
	//         "symbol": "ETH_USDC",
	//         "takeProfitLimitPrice": null,
	//         "takeProfitTriggerBy": null,
	//         "takeProfitTriggerPrice": null,
	//         "timeInForce": "GTC",
	//         "triggerBy": null,
	//         "triggerPrice": null,
	//         "triggerQuantity": null,
	//         "triggeredAt": null
	//     }
	//
	// fetchOpenOrders
	//     {
	//         "clientId": 123456789,
	//         "createdAt": 1753626206762,
	//         "executedQuantity": "0",
	//         "executedQuoteQuantity": "0",
	//         "id": "4228978331",
	//         "orderType": "Limit",
	//         "postOnly": true,
	//         "price": "3000",
	//         "quantity": "0.001",
	//         "reduceOnly": null,
	//         "relatedOrderId": null,
	//         "selfTradePrevention": "RejectTaker",
	//         "side": "Bid",
	//         "status": "New",
	//         "stopLossLimitPrice": null,
	//         "stopLossTriggerBy": null,
	//         "stopLossTriggerPrice": null,
	//         "strategyId": null,
	//         "symbol": "ETH_USDC",
	//         "takeProfitLimitPrice": null,
	//         "takeProfitTriggerBy": null,
	//         "takeProfitTriggerPrice": null,
	//         "timeInForce": "GTC",
	//         "triggerBy": null,
	//         "triggerPrice": null,
	//         "triggerQuantity": null,
	//         "triggeredAt": null
	//     }
	//
	// fetchOrders
	//     {
	//         "clientId": null,
	//         "createdAt": "2025-07-27T18:05:40.897",
	//         "executedQuantity": "0",
	//         "executedQuoteQuantity": "0",
	//         "expiryReason": null,
	//         "id": "4239996998",
	//         "orderType": "Limit",
	//         "postOnly": false,
	//         "price": "4500",
	//         "quantity": null,
	//         "quoteQuantity": null,
	//         "selfTradePrevention": "RejectTaker",
	//         "side": "Ask",
	//         "status": "Cancelled",
	//         "stopLossLimitPrice": null,
	//         "stopLossTriggerBy": null,
	//         "stopLossTriggerPrice": null,
	//         "strategyId": null,
	//         "symbol": "ETH_USDC",
	//         "systemOrderType": null,
	//         "takeProfitLimitPrice": null,
	//         "takeProfitTriggerBy": null,
	//         "takeProfitTriggerPrice": null,
	//         "timeInForce": "GTC",
	//         "triggerBy": null,
	//         "triggerPrice": "4300",
	//         "triggerQuantity": "0.001"
	//     }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var timestamp *int64 = this.SafeInteger(order, "createdAt")
	var timestamp2 *int64 = this.Parse8601(this.SafeString(order, "createdAt"))
	if timestamp2 != nil {
		timestamp = timestamp2
	}
	var id *string = this.SafeString(order, "id")
	var clientOrderId *string = this.SafeString(order, "clientId")
	var symbol *string = this.SafeSymbol(this.SafeString(order, "symbol"), market)
	var typeVar *string = this.SafeStringLower(order, "orderType")
	var timeInForce *string = this.SafeString(order, "timeInForce")
	var side *string = this.ParseOrderSide(this.SafeString(order, "side"))
	var amount *string = this.SafeString2(order, "quantity", "triggerQuantity")
	var price *string = this.SafeString(order, "price")
	var cost *string = this.SafeString(order, "executedQuoteQuantity")
	var status *string = this.ParseOrderStatus(this.SafeString(order, "status"))
	var triggerPrice *string = this.SafeString(order, "triggerPrice")
	var filled *string = this.SafeString(order, "executedQuantity")
	var reduceOnly *bool = this.SafeBool(order, "reduceOnly")
	var postOnly *bool = this.SafeBool(order, "postOnly")
	var stopLossPrice *string = this.SafeString2(order, "stopLossLimitPrice", "stopLossTriggerPrice")
	var takeProfitPrice *string = this.SafeString2(order, "takeProfitLimitPrice", "takeProfitTriggerPrice")
	return this.SafeOrder(map[string]any{
		"info":               order,
		"id":                 id,
		"clientOrderId":      clientOrderId,
		"timestamp":          timestamp,
		"datetime":           this.Iso8601(timestamp),
		"lastTradeTimestamp": nil,
		"symbol":             symbol,
		"type":               typeVar,
		"timeInForce":        timeInForce,
		"postOnly":           postOnly,
		"reduceOnly":         reduceOnly,
		"side":               side,
		"price":              price,
		"triggerPrice":       triggerPrice,
		"stopLossPrice":      stopLossPrice,
		"takeProfitPrice":    takeProfitPrice,
		"amount":             amount,
		"cost":               cost,
		"average":            nil,
		"filled":             filled,
		"remaining":          nil,
		"status":             status,
		"fee":                nil,
		"trades":             nil,
	}, market)
}
func (this *Backpack) ParseOrderStatus(status *string) *string {
	var statuses map[string]any = map[string]any{
		"New":             "open",
		"Filled":          "closed",
		"Cancelled":       "canceled",
		"Expired":         "canceled",
		"PartiallyFilled": "open",
		"TriggerPending":  "open",
		"TriggerFailed":   "rejected",
	}
	return this.SafeString(statuses, status, status)
}
func (this *Backpack) ParseOrderSide(side *string) *string {
	var sides map[string]any = map[string]any{
		"Bid": "buy",
		"Ask": "sell",
	}
	return this.SafeString(sides, side, side)
}

/**
 * @method
 * @name backpack#fetchPositions
 * @description fetch all open positions
 * @see https://docs.backpack.exchange/#tag/Futures/operation/get_positions
 * @param {string[]|undefined} symbols list of unified market symbols
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object[]} a list of [position structure]{@link https://docs.ccxt.com/?id=position-structure}
 */
func (this *Backpack) FetchPositionsAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchPositionsBody(ch, optionalArgs...)
	return ch
}
func (this *Backpack) fetchPositionsBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var symbols []string = GetArgStringSlice(optionalArgs, 0, nil)
	_ = symbols
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}

	var response []any = ListTyped(PanicOnError((<-this.PrivateGetApiV1Position(params)).Raw))
	var positions any = this.ParsePositions(response)
	if this.IsEmpty(symbols) {

		ch <- positions
		return nil
	}
	var symbolsNormalized []string = this.MarketSymbols(symbols)

	ch <- this.FilterByArrayPositions(positions, "symbol", symbolsNormalized, false)
	return nil
}
func (this *Backpack) ParsePosition(position any, optionalArgs ...any) any {
	//
	// fetchPositions
	//     {
	//         "breakEvenPrice": "3831.3630555555555555555555556",
	//         "cumulativeFundingPayment": "-0.009218",
	//         "cumulativeInterest": "0",
	//         "entryPrice": "3826.8888888888888888888888889",
	//         "estLiquidationPrice": "0",
	//         "imf": "0.02",
	//         "imfFunction": {
	//             "base": "0.02",
	//             "factor": "0.0000935",
	//             "type": "sqrt"
	//         },
	//         "markPrice": "3787.46813304",
	//         "mmf": "0.0125",
	//         "mmfFunction": {
	//             "base": "0.0125",
	//             "factor": "0.0000561",
	//             "type": "sqrt"
	//         },
	//         "netCost": "13.7768",
	//         "netExposureNotional": "13.634885278944",
	//         "netExposureQuantity": "0.0036",
	//         "netQuantity": "0.0036",
	//         "pnlRealized": "0",
	//         "pnlUnrealized": "-0.141914",
	//         "positionId": "4238420454",
	//         "subaccountId": null,
	//         "symbol": "ETH_USDC_PERP",
	//         "userId":1813870
	//     }
	//
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var id *string = this.SafeString(position, "positionId")
	var marketId *string = this.SafeString(position, "symbol")
	var marketResolved map[string]any = this.SafeMarket(marketId, market)
	var symbol *string = SafeStringPtr(marketResolved["symbol"])
	var entryPrice *string = this.SafeString(position, "entryPrice")
	var markPrice *string = this.SafeString(position, "markPrice")
	var netCost *string = this.SafeString(position, "netCost")
	var hedged any = false
	var side any = "long"
	if Precise.StringLt(netCost, "0") {
		side = "short"
	}
	if netCost == nil {
		hedged = nil
		side = nil
	}
	var unrealizedPnl *string = this.SafeString(position, "pnlUnrealized")
	var realizedPnl *string = this.SafeString(position, "pnlRealized")
	var liquidationPrice *string = this.SafeString(position, "estLiquidationPrice")
	return this.SafePosition(map[string]any{
		"info":                        position,
		"id":                          id,
		"symbol":                      symbol,
		"timestamp":                   this.Parse8601(this.SafeString(position, "timestamp")),
		"datetime":                    this.Iso8601(this.Parse8601(this.SafeString(position, "timestamp"))),
		"lastUpdateTimestamp":         nil,
		"hedged":                      hedged,
		"side":                        side,
		"contracts":                   this.SafeString(position, "netExposureQuantity"),
		"contractSize":                nil,
		"entryPrice":                  entryPrice,
		"markPrice":                   markPrice,
		"lastPrice":                   nil,
		"notional":                    Precise.StringAbs(netCost),
		"leverage":                    nil,
		"collateral":                  nil,
		"initialMargin":               nil,
		"initialMarginPercentage":     this.SafeString(position, "imf"),
		"maintenanceMargin":           nil,
		"maintenanceMarginPercentage": this.SafeString(position, "mmf"),
		"realizedPnl":                 realizedPnl,
		"unrealizedPnl":               unrealizedPnl,
		"liquidationPrice":            liquidationPrice,
		"marginMode":                  nil,
		"marginRatio":                 nil,
		"percentage":                  nil,
		"stopLossPrice":               nil,
		"takeProfitPrice":             nil,
	})
}

