func (this *Backpack) Nonce() any {
	var timeDifference *int64 = this.SafeInteger(this.Options, "timeDifference")
	if timeDifference == nil {
		panic(ExchangeError(this.Id + " nonce() requires a numeric options[\"timeDifference\"]"))
	}
	return Subtract(this.Milliseconds(), timeDifference)
}
func (this *Backpack) Sign(path string, optionalArgs ...any) any {
	api := GetArg(optionalArgs, 0, "public")
	_ = api
	var method string = GetArgString(optionalArgs, 1, "GET")
	_ = method
	params := GetArg(optionalArgs, 2, map[string]any{})
	_ = params
	headers := GetArg(optionalArgs, 3, nil)
	_ = headers
	var body *string = GetArgStringPtr(optionalArgs, 4, nil)
	_ = body
	var endpoint string = "/" + path
	var apiUrl *string = this.SafeString(GetValue(this.Urls, "api"), api)
	if apiUrl == nil {
		panic(ExchangeError(this.Id + " sign() has no API URL for this endpoint"))
	}
	var url any = apiUrl
	var sortedParams any = func() any {
		if IsArray(params) {
			return params
		}
		return this.Keysort(params)
	}()
	var headersSigned any = nil
	var bodySigned *string = nil
	if api == "private" {
		this.CheckRequiredCredentials()
		var ts string = ToString(this.Nonce())
		var recvWindow *string = this.SafeString2(this.Options, "recvWindow", "X-Window", "5000")
		var optionInstructions map[string]any = SafeMapTyped(this.Options, "instructions")
		var optionPathInstructions map[string]any = SafeMapTyped(optionInstructions, path)
		var instruction *string = this.SafeString(optionPathInstructions, method, "")
		var payload any = ""
		if (path == "api/v1/orders") && (method == "POST") {
			payload = this.GenerateBatchPayload(sortedParams, ts, recvWindow, instruction)
		} else {
			var queryString string = this.Urlencode(sortedParams)
			if len(queryString) > 0 {
				queryString += "&"
			}
			payload = "instruction=" + *instruction + "&" + queryString + "timestamp=" + ts + "&window=" + *recvWindow
		}
		var secretBytes []byte = this.Base64ToBinary(this.Secret)
		var seed any = this.ArraySlice(secretBytes, 0, 32)
		var signature string = Eddsa(this.Encode(payload), seed, ed25519)
		headersSigned = map[string]any{
			"X-Timestamp": ts,
			"X-Window":    recvWindow,
			"X-API-Key":   this.ApiKey,
			"X-Signature": signature,
			"X-Broker-Id": "1400",
		}
		if method != "GET" {
			bodySigned = SafeStringPtr(this.Json(sortedParams))
			AddElementToObject(headersSigned, "Content-Type", "application/json")
		}
	}
	if method == "GET" {
		var query string = this.Urlencode(sortedParams)
		if len(query) != 0 {
			endpoint += "?" + query
		}
	}
	url = Add(url, endpoint)
	var headersResolved any = func() any {
		if api == "private" {
			return headersSigned
		}
		return headers
	}()
	var bodyResolved *string = body
	if ((api == "private")) && (method != "GET") {
		bodyResolved = bodySigned
	}
	return map[string]any{
		"url":     url,
		"method":  method,
		"body":    bodyResolved,
		"headers": headersResolved,
	}
}
func (this *Backpack) GenerateBatchPayload(params any, ts string, recvWindow any, instruction any) any {
	var payload any = ""
	for i := 0; i < GetArrayLength(params); i++ {
		var order map[string]any = MapTyped(this.SafeDict(params, i, map[string]any{}))
		var sortedOrder map[string]any = this.Keysort(order)
		var orderQuery string = this.Urlencode(sortedOrder)
		payload = Add(payload, Add(Add(Add(Add("instruction=", instruction), "&"), orderQuery), "&"))
		if i == (GetArrayLength(params) - 1) {
			payload = Add(payload, Add("timestamp="+ts+"&window=", recvWindow))
		}
	}
	return payload
}
func (this *Backpack) HandleErrors(code any, reason any, url any, method any, headers any, body any, response any, requestHeaders any, requestBody any) any {
	if IsEqual(response, nil) {
		return nil // fallback to default error handler
	}
	//
	// {"code":"INVALID_ORDER","message":"Invalid order"}
	// {"code":"INVALID_CLIENT_REQUEST","message":"Must specify both `triggerPrice` and `triggerQuantity` or neither"}
	//
	var errorCode *string = this.SafeString(response, "code")
	var message *string = this.SafeString(response, "message")
	if errorCode != nil {
		var feedback *string = SafeStringPtr(Add(this.Id+" ", body))
		this.ThrowExactlyMatchedException(this.Exceptions["exact"], errorCode, feedback)
		this.ThrowExactlyMatchedException(this.Exceptions["exact"], message, feedback)
		this.ThrowBroadlyMatchedException(this.Exceptions["broad"], message, feedback)
		panic(ExchangeError(feedback))
	}
	return nil
}

func NewBackpack(userConfig map[string]any) *Backpack {
	p := newBackpack()
	p.Init(userConfig)
	return p
}

func (this *Backpack) Init(userConfig map[string]any) {
	this.Exchange = Exchange{}
	this.Exchange.DerivedExchange = this
	this.Exchange.InitParent(userConfig, this.Describe().(map[string]any), this)
	this.exchangeTyped = NewExchangeTyped(&this.Exchange)
}

